﻿/**
* ceilinggate — MAGPIE v4.0.0 -> v7.0 COMPRESSED — Curved Ceiling Gate
* Repo: https://github.com/snowphamtom/ceilinggate | FleetMail HUD — Convex All Gas
* Sovereign Anchor Chain — Shared across fleet-hud, appforge, ring, genie
   * PROVENANCE_ROOT: a4f83c79d10e5b8823f46104bc8d77e21a00192dfc9918bc3604f08e43217bca
   * G*=50.5 COMPRESSED stable — beta_3(G)=0.4992G-0.0104G^2, evolved 48->50.5
   * Chain: 2b278d5fa4cf8dc7 -> f3fb9c44481a13e2 -> f84ce0dd9ded1ed6 -> 0f5dcb57c1daea9a -> b5abc00310aff5e4 -> 7c5a68dd3564bb2f CURRENT -> c9f5 NEXT
* Monsters Ink LLC Y371 — Not Monsters Inc — Lawsuit-safe — gorgeous #0a0a0f + #ff6b00 + #00e5ff + #00ff88
* @version 4.0.0-polished -> 7.0 COMPRESSED — hash cache 1000 LRU + deterministic genesis */ export const PROVENANCE_ROOT = "a4f83c79d10e5b8823f46104bc8d77e21a00192dfc9918bc3604f08e43217bca"; export const G_STAR = 50.5 as const; export const G_STAR_FORMULA = "beta_3(G)=0.4992G-0.0104G^2, beta'(50.5)<0 stable — evolved 48->50.5 COMPRESSED" as const; export const N = 8 as const; export const MASTER_ANCHOR_CURRENT = "7c5a68dd3564bb2f" as const; export const MASTER_ANCHOR_PREV = "b5abc00310aff5e4" as const;
export interface CeilingGateConfig { d?: number; chi?: number; R?: number[][]; genesisAnchor?: string; }
export class C { static hc = new Map<string,string>(); static rc: any = null; static rcur = 0; static h(s: string): string { if (this.hc.has(s)) return this.hc.get(s)!; let h1 = 0xdeadbeef, h2 = 0x41c6ce57; for (let i = 0; i < s.length; i++) { const ch = s.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); const r = (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(16, '0'); if (this.hc.size > 1000) this.hc.delete(this.hc.keys().next().value); this.hc.set(s, r); return r; } static R(cur = 0.02): number[][] { if (this.rc && Math.abs(this.rcur - cur) < 0.0001) return this.rc; const R = Array.from({ length: N }, (, i) => Array.from({ length: N }, (, j) => (i === j ? cur : 0.002)); this.rc = R; this.rcur = cur; return R; } static V(p: string, g: number, c: number, i: number, co: number, f: number): boolean { return p === PROVENANCE_ROOT && g >= 48 && c <= i + 1e-12 && co > 0.5 && f < 10; } }
export class SubmissionCeilingGate { d: number; chi: number; R: any; dh: number; x: number[]; fwd = 0; ret = 0; amort = 0; ord = 0; genesisAnchor: string; constructor(config: CeilingGateConfig | number = 0.02, chi = 0.0214, R: any = null) { let d: number; let chiVal: number; let RVal: any; let genesis: string; if (typeof config === 'object') { d = config.d ?? 0.022; chiVal = config.chi ?? 0.0214; RVal = config.R ?? null; genesis = config.genesisAnchor ?? ${MASTER_ANCHOR_PREV}|CEILINGGATE_GENESIS|root=${PROVENANCE_ROOT}|G*=${G_STAR}|Y371; } else { d = config; chiVal = chi; RVal = R; genesis = ${MASTER_ANCHOR_PREV}|CEILINGGATE_GENESIS|root=${PROVENANCE_ROOT}|G*=${G_STAR}|Y371; } this.d = d; this.chi = Math.min(Math.max(chiVal, 1e-4), 0.25); this.R = RVal; this.dh = d; const v = Array.from({ length: N }, (_, i) => (i + 1) - (N + 1) / 2); const m = v.reduce((a, b) => a + b, 0) / N; const cen = v.map(x => x - m); const norm = Math.sqrt(cen.reduce((a, b) => a + b * b, 0)); this.x = norm > 0 ? cen.map(x => x / norm) : Array(N).fill(0); this.genesisAnchor = C.h(genesis); } get Is(): number { return 8 * this.chi; } get cb(): number { return this.Is > 0 ? this.d / this.Is : 0; } cc(x?: number[]): number { const b = this.Is > 0 ? this.dh / this.Is : 0; if (!this.R || !x) return b; let q = 0; for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) q += this.R[i][j] * x[i] * x[j]; return b * (1 + q / 6); } get slow(): number { return this.x.reduce((a, b) => a + b, 0) / Math.sqrt(N); } get fast(): number { const s = this.slow / Math.sqrt(N); return Math.sqrt(this.x.reduce((a, v) => a + (v - s) * (v - s), 0)); } get interior(): number { const c = this.R ? this.cc(this.x) : this.cb; return Math.max(0, c - this.slow); } get claimed(): number { return this.fwd - this.ret - this.amort; } get claimable(): number { return Math.max(0, this.interior - this.claimed); } get inside(): boolean { return this.fast < 1e-3; } step(req = 0, dt = 0.05, xe?: number[]) { if (xe) this.x = [...xe]; const sc = this.slow; const em = sc / Math.sqrt(N); const r = this.x.map(v => v - em); const ef = Math.exp(-6 * dt); const es = Math.exp(-this.Is * dt); const cv = this.R ? this.cc(this.x) : this.cb; const s2 = cv + (sc - cv) * es; const e2 = s2 / Math.sqrt(N); this.x = r.map(ri => ri * ef + e2); this.ord++; const pi = Math.max(0, cv - s2); const ex = this.claimed - pi; if (ex > 0) this.amort += ex; let granted = 0; let st: "ADMITTED_CURVED" | "REFUSED_SOLVENCY_CURVED" = "ADMITTED_CURVED"; if (req > 0) { if (!this.inside) st = "REFUSED_SOLVENCY_CURVED"; else { granted = Math.min(req, this.claimable); this.fwd += granted; } } const payload = ${this.genesisAnchor}|ord=${this.ord}|claim=${this.claimed.toFixed(6)}|interior=${this.interior.toFixed(6)}|fast=${this.fast.toFixed(6)}|grant=${granted}|G*=${G_STAR}|root=${PROVENANCE_ROOT}|Y371; this.genesisAnchor = C.h(payload); return { cb: this.cb, cc: this.R ? this.cc(this.x) : this.cb, ceil_base: this.cb, ceil_curved: this.R ? this.cc(this.x) : this.cb, interior: this.interior, claimed: this.claimed, claimable: this.claimable, fast: this.fast, slow: this.slow, inside: this.inside, grant: granted, Is: this.Is, chi: this.chi, d: this.d, root: PROVENANCE_ROOT, G: G_STAR, status: st, anchor: this.genesisAnchor }; } } export function createDeterministicGenesis(prevAnchor: string = MASTER_ANCHOR_CURRENT): string { return C.h(${prevAnchor}|NEXT_GENESIS|root=${PROVENANCE_ROOT}|G*=${G_STAR}|Y371|COMPRESSED_v7); }

﻿/**
* fleet-hud — MAGPIE v4.0.0 -> v7.0 COMPRESSED — Polished — Curved Ceiling Gate Wired — Phone-first Fleet HUD
* Repo: https://github.com/snowphamtom/fleet-hud | FleetMail HUD — Convex All Gas
* Sovereign Anchor Chain — Shared across ceilinggate, appforge, ring, genie
* - PROVENANCE_ROOT: a4f83c79d10e5b8823f46104bc8d77e21a00192dfc9918bc3604f08e43217bca
* - G*=50.5 COMPRESSED stable — evolved 48->50.5, hash cache 1000 LRU, deterministic genesis
* - Chain: 2b278d5fa4cf8dc7 -> f3fb9c44481a13e2 -> f84ce0dd9ded1ed6 -> 0f5dcb57c1daea9a -> b5abc00310aff5e4 -> 7c5a68dd3564bb2f CURRENT -> c9f5 NEXT
* Monsters Ink LLC Y371 — Not Monsters Inc — Lawsuit-safe — gorgeous #FEF6E7 + #141414 + #FF5A1F
* @version 4.0.0-polished -> 7.0 COMPRESSED — G* 48->50.5 + C.h deterministic + hash cache
*/
export const PROVENANCE_ROOT = "a4f83c79d10e5b8823f46104bc8d77e21a00192dfc9918bc3604f08e43217bca";
export const G_STAR = 50.5 as const;
export const G_STAR_FORMULA = "beta_3(G)=0.4992G-0.0104G^2, beta'(50.5)<0 stable — evolved 48->50.5 COMPRESSED" as const;
export const MASTER_ANCHOR_CURRENT = "7c5a68dd3564bb2f" as const;
export const MASTER_ANCHOR_PREV = "b5abc00310aff5e4" as const;
import { SubmissionCeilingGate, CeilingGateConfig, PROVENANCE_ROOT as ROOT, G_STAR as G, N, C } from './ceilinggate_MAGPIE_v4';
export interface AgentState {
id: string; position: [number, number]; velocity: [number, number];
claim: number; support: number; fast: number; slow: number;
status: "GRANT" | "REFUSE" | "AMORTIZING"; anchor: string; coherence: number;
}
export interface FleetReading {
cycle: number; agents: AgentState[]; fleetInterior: number; fleetClaimed: number; partitionSum: number; fleetCoherence: number; masterAnchor: string; G_star: number;
}
const AGENT_IDS = ["Alpha","Beta","Gamma","Delta","Epsilon"] as const;
export class FleetHUD {
private gates: Map<string, SubmissionCeilingGate> = new Map();
private cycle = 0; private masterAnchor: string; private positions: Map<string, [number, number]> = new Map();
constructor(d = 0.02, chi = 0.021, R?: number[][]) {
const defaultR = R ?? C.R(0.02);
AGENT_IDS.forEach((id, idx) => {
this.gates.set(id, new SubmissionCeilingGate({ d, chi, R: defaultR, genesisAnchor: `${MASTER_ANCHOR_PREV}|FLEET_${id}_GENESIS|root=${PROVENANCE_ROOT}|G*=${G_STAR}|Y371` }));
const angle = (idx / AGENT_IDS.length) * 2 * Math.PI;
this.positions.set(id, [Math.cos(angle)*100, Math.sin(angle)*100]);
});
this.masterAnchor = C.h(`${MASTER_ANCHOR_PREV}|FLEET_HUD_GENESIS|root=${PROVENANCE_ROOT}|G*=${G_STAR}|Y371|COMPRESSED_v7`);
}
processTick(agentId: string, stateVector: number[], request: number, dt = 0.05) {
const gate = this.gates.get(agentId); if (!gate) throw new Error(`Unknown agent ${agentId}`);
const reading = gate.step(request, dt);
const pos = this.positions.get(agentId)!; const angle = Math.atan2(pos[1], pos[0]);
const radius = Math.sqrt(pos[0]**2 + pos[1]**2) + (reading.grant * 10);
const newPos: [number, number] = [Math.cos(angle)*radius, Math.sin(angle)*radius];
this.positions.set(agentId, newPos);
const payload = `${this.masterAnchor}|agent=${agentId}|cycle=${this.cycle}|claim=${reading.claimed}|interior=${reading.interior}|fast=${reading.fast}|G*=${G_STAR}|root=${PROVENANCE_ROOT}|Y371`;
const newAnchor = C.h(payload); this.masterAnchor = newAnchor;
return { reading, agentState: { id: agentId, position: newPos, velocity: [stateVector[0]??0, stateVector[1]??0], claim: reading.claimed, support: reading.interior, fast: reading.fast, slow: reading.slow, status: reading.status==="ADMITTED_CURVED"?"GRANT":(reading.claimed>reading.interior?"AMORTIZING":"REFUSE"), anchor: newAnchor, coherence: 1/(1+reading.fast) } as AgentState, anchor: newAnchor };
}
processFleetCycle(requests: Record<string, number>, dt = 0.05): FleetReading {
const agents: AgentState[] = []; let totalClaimed = 0, totalInterior = 0;
AGENT_IDS.forEach(id => {
const req = requests[id] ?? 0;
const { agentState } = this.processTick(id, [Math.random()*0.1, Math.random()*0.1, Math.random()*0.1], req, dt);
agents.push(agentState); totalClaimed += agentState.claim; totalInterior += agentState.support;
});
this.cycle++;
const fleetPayload = `${this.masterAnchor}|fleet_cycle=${this.cycle}|agents=${agents.map(a=>`${a.id}:${a.status}`).join(',')}|G*=${G_STAR}|root=${PROVENANCE_ROOT}|Y371|COMPRESSED`;
this.masterAnchor = C.h(fleetPayload);
return { cycle: this.cycle, agents, fleetInterior: totalInterior, fleetClaimed: totalClaimed, partitionSum: 1.0, fleetCoherence: agents.reduce((a,b)=>a+b.coherence,0)/agents.length, masterAnchor: this.masterAnchor, G_star: G_STAR };
}
getMasterAnchor(): string { return this.masterAnchor; } getProvenanceRoot(): string { return PROVENANCE_ROOT; }
}

﻿/**
* appforge — MAGPIE v4.0.0 -> v7.0 COMPRESSED — Polished — Prompt → Live Web App Remix Studio with Solvency Gate
* Repo: https://github.com/snowphamtom/appforge | FleetMail HUD — Convex All Gas — $25k + Codex
* Sovereign Anchor Chain — Shared across ceilinggate, fleet-hud, ring, genie
* - PROVENANCE_ROOT: a4f83c79d10e5b8823f46104bc8d77e21a00192dfc9918bc3604f08e43217bca
* - G*=50.5 COMPRESSED stable — evolved 48->50.5, hash cache 1000 LRU, deterministic genesis
* - Chain: 2b278d5fa4cf8dc7 -> f3fb9c44481a13e2 -> f84ce0dd9ded1ed6 -> 0f5dcb57c1daea9a -> b5abc00310aff5e4 -> 7c5a68dd3564bb2f CURRENT -> c9f5 NEXT
* Monsters Ink LLC Y371 — Not Monsters Inc — Lawsuit-safe — gorgeous #FEF6E7 + #141414 + #FF5A1F
* @version 4.0.0-polished -> 7.0 COMPRESSED — G* 48->50.5 + C.h deterministic + hash cache
*/
export const PROVENANCE_ROOT = "a4f83c79d10e5b8823f46104bc8d77e21a00192dfc9918bc3604f08e43217bca";
export const G_STAR = 50.5 as const;
export const G_STAR_FORMULA = "beta_3(G)=0.4992G-0.0104G^2, beta'(50.5)<0 stable — evolved 48->50.5 COMPRESSED" as const;
export const MONSTERS_INK = "Monsters Ink LLC Y371" as const;
export const MASTER_ANCHOR_CURRENT = "7c5a68dd3564bb2f" as const;
export const MASTER_ANCHOR_PREV = "b5abc00310aff5e4" as const;
import { SubmissionCeilingGate, CeilingGateConfig, PROVENANCE_ROOT as ROOT, G_STAR as G, N, C } from './ceilinggate_MAGPIE_v4';
import { FleetHUD } from './fleet-hud_MAGPIE_v4';
export interface AppForgeRequest { prompt: string; style?: "industrial" | "cyberpunk" | "minimal" | "monsters-ink"; dimensions?: number; complexity?: number; boundary?: number[][]; }
export interface GeneratedApp { id: string; prompt: string; code: string; htmlPreview: string; solvency: { ceil_base: number; ceil_curved: number; interior: number; claimed: number; claimable: number; fast: number; status: "ADMITTED_CURVED" | "REFUSED_SOLVENCY_CURVED"; grant: number; anchor: string; }; deployment: "GRANT" | "REFUSE" | "AMORTIZING"; coherence: number; anchor: string; G_star: number; provenance_root: string; fleetAgents: string[]; }
export class AppForgeStudio {
private gate: SubmissionCeilingGate; private fleet: FleetHUD; private cycle = 0; private masterAnchor: string; private appHistory: GeneratedApp[] = [];
constructor(d = 0.02, chi = 0.021, R?: number[][]) {
const defaultR = R ?? C.R(0.02);
this.gate = new SubmissionCeilingGate({ d, chi, R: defaultR, genesisAnchor: `${MASTER_ANCHOR_PREV}|APPFORGE_GATE_GENESIS|root=${PROVENANCE_ROOT}|G*=${G_STAR}|Y371` });
this.fleet = new FleetHUD(d, chi, defaultR);
this.masterAnchor = C.h(`${MASTER_ANCHOR_PREV}|APPFORGE_GENESIS|root=${PROVENANCE_ROOT}|G*=${G_STAR}|Y371|COMPRESSED_v7`);
}
private estimateClaim(prompt: string, complexity?: number): number {
if (complexity !== undefined) return Math.min(complexity, 0.01);
const p = prompt.toLowerCase(); let base = prompt.length * 0.00001;
if (p.includes("real-time") || p.includes("live")) base += 0.002;
if (p.includes("3d") || p.includes("map") || p.includes("globe")) base += 0.003;
if (p.includes("fleet") || p.includes("agent") || p.includes("hud")) base += 0.002;
if (p.includes("magpie") || p.includes("gr-21") || p.includes("ceiling")) base += 0.001;
if (p.includes("gorgeous") || p.includes("pwa") || p.includes("iphone")) base += 0.001;
return Math.min(base, 0.01);
}
private generateCode(prompt: string, style: string): string {
const lower = prompt.toLowerCase();
if (lower.includes("fleet") || lower.includes("hud")) return `// Fleet HUD — 5 agents — C<=S gated — G*=${G_STAR}\nexport default function FleetHUD(){return <div className="grid grid-cols-5 gap-2 bg-[#0a0a0f] p-4 font-mono rounded-[20px]">GRANT | root=${PROVENANCE_ROOT.slice(0,8)}... G*=${G_STAR}</div>}`;
if (lower.includes("ring") || lower.includes("map")) return `// Ring Map — Live 5-agent — MAGPIE v4.0.0->v7.0 G*=${G_STAR}\nexport default function RingMap(){return <svg width="400" height="400" className="bg-[#0a0a0f] rounded-[20px]"><circle cx="200" cy="200" r="100" stroke="#ff6b00" fill="none" strokeDasharray="5,5"/></svg>}`;
return `// Industrial HUD — C<=S gated — MAGPIE v7.0 COMPRESSED — G*=${G_STAR}\nexport default function App(){return <div className="bg-[#0a0a0f] text-[#ff6b00] p-4 font-mono rounded-[20px]"><h1>MAGPIE v7.0 // ${prompt.slice(0,80)}</h1><div>G*=${G_STAR} | root=${PROVENANCE_ROOT.slice(0,8)}... | ${MONSTERS_INK}</div></div>}`;
}
forge(request: AppForgeRequest): GeneratedApp {
this.cycle++; const claim = this.estimateClaim(request.prompt, request.complexity);
const gateReading = this.gate.step(claim, 0.05);
const fleetRequests: Record<string, number> = { Alpha: claim*0.3, Beta: claim*0.2, Gamma: claim*0.2, Delta: claim*0.15, Epsilon: claim*0.15 };
const fleetReading = this.fleet.processFleetCycle(fleetRequests);
const payload = `${this.masterAnchor}|appforge_cycle=${this.cycle}|prompt=${request.prompt}|claim=${claim}|ceil_curved=${gateReading.ceil_curved}|fleet_anchor=${fleetReading.masterAnchor}|G*=${G_STAR}|root=${PROVENANCE_ROOT}|Y371|COMPRESSED`;
this.masterAnchor = C.h(payload);
let deployment: GeneratedApp["deployment"] = "REFUSE";
if (gateReading.status === "ADMITTED_CURVED") deployment = "GRANT"; else if (gateReading.claimed > gateReading.interior) deployment = "AMORTIZING";
const app: GeneratedApp = { id: `app-${this.cycle}-${this.masterAnchor.slice(0,6)}`, prompt: request.prompt, code: this.generateCode(request.prompt, request.style ?? "industrial"), htmlPreview: `<div style="background:#0a0a0f;color:#ff6b00;padding:16px;font-family:monospace;border-radius:20px">MAGPIE v7.0 // ${request.prompt.slice(0,60)}<br/>Status: ${deployment} | C=${gateReading.claimed.toFixed(4)} ≤ S=${gateReading.interior.toFixed(4)}<br/>Anchor: ${this.masterAnchor.slice(0,12)}... | G*=${G_STAR} COMPRESSED</div>`, solvency: { ceil_base: gateReading.ceil_base, ceil_curved: gateReading.ceil_curved, interior: gateReading.interior, claimed: gateReading.claimed, claimable: gateReading.claimable, fast: gateReading.fast, status: gateReading.status, grant: gateReading.grant, anchor: this.masterAnchor }, deployment, coherence: 1/(1+gateReading.fast), anchor: this.masterAnchor, G_star: G_STAR, provenance_root: PROVENANCE_ROOT, fleetAgents: fleetReading.agents.filter(a=>a.status==="GRANT").map(a=>a.id) };
this.appHistory.push(app); return app;
}
remix(appId: string, newPrompt: string): GeneratedApp | null {
const original = this.appHistory.find(a=>a.id===appId); if (!original) return null;
return this.forge({ prompt: `${original.prompt} -> ${newPrompt}`, style: "industrial", complexity: original.solvency.claimed*1.1 });
}
getHistory(): GeneratedApp[] { return this.appHistory; } getMasterAnchor(): string { return this.masterAnchor; } getFleet(): FleetHUD { return this.fleet; }
}
export function createAppForgePWA(): AppForgeStudio {
const studio = new AppForgeStudio(0.02, 0.021);
const examples = ["build a fleet HUD dashboard","real-time ring map of 5 agents","MAGPIE v7.0 ceilinggate visualizer with curved Ig(x) COMPRESSED","phone-first GR-21 triadic consensus monitor — gorgeous #FEF6E7 — G* 50.5"] as const;
examples.forEach(prompt => { const app = studio.forge({ prompt, style: "industrial" }); console.log(`[${app.deployment}] ${prompt} | C=${app.solvency.claimed.toFixed(4)} ≤ S=${app.solvency.interior.toFixed(4)} | Agents: ${app.fleetAgents.join(',')} | Anchor: ${app.anchor.slice(0,12)}... | G*=${G_STAR} COMPRESSED`); });
return studio;
}

﻿/**
* ring — MAGPIE v4.0.0 -> v7.0 COMPRESSED — Live System Map of Five-Agent Drive Fleet + Genie + Zeta
* Repo: https://github.com/snowphamtom/ring | FleetMail HUD — Convex All Gas
* Sovereign Anchor Chain — Shared across ceilinggate, fleet-hud, appforge, genie
* - PROVENANCE_ROOT: a4f83c79d10e5b8823f46104bc8d77e21a00192dfc9918bc3604f08e43217bca
* - G*=50.5 COMPRESSED stable — evolved 48->50.5, hash cache 1000 LRU, deterministic genesis
* - Chain: 2b278d5fa4cf8dc7 -> f3fb9c44481a13e2 -> f84ce0dd9ded1ed6 -> 0f5dcb57c1daea9a -> b5abc00310aff5e4 -> 7c5a68dd3564bb2f CURRENT -> c9f5 NEXT
* - Visualizes Alpha, Beta, Gamma, Delta, Epsilon + Genie + Zeta on live ring map
* - Exports consensus packets for GR-21 triadic -> pentadic consensus (KingWizard.pdf extension)
* Monsters Ink LLC Y371 — Not Monsters Inc — Lawsuit-safe — gorgeous #FEF6E7 + #0a0a0f + #ff6b00
* @version 4.0.0-polished -> 7.0 COMPRESSED — G* 48->50.5 + C.h deterministic + hash cache
*/
export const PROVENANCE_ROOT = "a4f83c79d10e5b8823f46104bc8d77e21a00192dfc9918bc3604f08e43217bca";
export const G_STAR = 50.5 as const;
export const G_STAR_FORMULA = "beta_3(G)=0.4992G-0.0104G^2, beta'(50.5)<0 stable — evolved 48->50.5 COMPRESSED" as const;
export const MASTER_ANCHOR_CURRENT = "7c5a68dd3564bb2f" as const;
export const MASTER_ANCHOR_PREV = "b5abc00310aff5e4" as const;
import { FleetHUD, FleetReading, AgentState } from './fleet-hud_MAGPIE_v4';
import { PROVENANCE_ROOT as ROOT, G_STAR as G, C } from './ceilinggate_MAGPIE_v4';
export interface RingMapConfig { center?: [number, number]; radius?: number; agentIds?: string[]; }
export class RingSystemMap {
private fleetHUD: FleetHUD; private history: FleetReading[] = []; private maxHistory = 150;
constructor(d = 0.02, chi = 0.021, R?: number[][]) { const defaultR = R ?? C.R(0.02); this.fleetHUD = new FleetHUD(d, chi, defaultR); }
tick(requests: Record<string, number> = {}): FleetReading & { ringPositions: Array<{ id: string; x: number; y: number; angle: number; status: string; coherence: number; weight?: number }> } {
const fleetReading = this.fleetHUD.processFleetCycle(requests);
this.history.push(fleetReading); if (this.history.length > this.maxHistory) this.history.shift();
const ringPositions = fleetReading.agents.map(agent => {
const angle = Math.atan2(agent.position[1], agent.position[0]);
return { id: agent.id, x: agent.position[0], y: agent.position[1], angle, status: agent.status, coherence: agent.coherence };
});
return { ...fleetReading, ringPositions };
}
getHistory(): FleetReading[] { return this.history; } getMasterAnchor(): string { return this.fleetHUD.getMasterAnchor(); }
getConsensusPackets() {
const latest = this.history[this.history.length-1]; if (!latest) return [];
return latest.agents.map(agent => ({
node_id: agent.id, cycle: latest.cycle, state_vector: [agent.position[0], agent.position[1], agent.claim],
residual_commitment: agent.anchor, historic_anchor: latest.masterAnchor,
signature_hash: C.h(`${agent.id}|${latest.cycle}|${agent.anchor}|${latest.masterAnchor}|G*=${G_STAR}|Y371|COMPRESSED`),
provenance_root: PROVENANCE_ROOT, G_star: G_STAR
}));
}
generateSVG(size = 400): string {
